android.extraProguardRules:
# ML Kit carga sus modelos por reflexion y R8 no lo ve. Ni image-labeling ni
# image-labeling-custom traen reglas propias en su AAR —barcode-scanning si—,
# asi que van aca. Los usa el modulo modules/reconocedor.
-keep class com.google.mlkit.** { *; }
-keep class com.google.android.gms.internal.mlkit_** { *; }
-dontwarn com.google.mlkit.**

# El interprete de TensorFlow Lite, que es lo que corre el modelo propio por
# debajo de image-labeling-custom. Entra por JNI, asi que para R8 nadie lo usa.
-keep class org.tensorflow.lite.** { *; }
-dontwarn org.tensorflow.lite.**

# El modulo nativo del color dominante, la otra mitad del reconocedor.
-keep class com.reactnativeimagecolors.** { *; }
